/* Reset & Base Styles */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;

  /* Color Palette */
  --bg-main: #f1f5f9;
  --bg-card: #ffffff;
  --text-primary: #0f172a;
  --text-secondary: #475569;
  --text-muted: #64748b;
  --border-color: #cbd5e1;
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #dbeafe;

  /* Table Statuses */
  --status-available-bg: #ecfdf5;
  --status-available-border: #10b981;
  --status-available-text: #065f46;

  --status-occupied-bg: #fffbeb;
  --status-occupied-border: #f59e0b;
  --status-occupied-text: #92400e;

  --status-dirty-bg: #fef2f2;
  --status-dirty-border: #ef4444;
  --status-dirty-text: #991b1b;

  /* Queue Statuses */
  --queue-waiting-bg: #f0f9ff;
  --queue-waiting-border: #0ea5e9;
  --queue-waiting-text: #0369a1;

  --queue-notified-bg: #faf5ff;
  --queue-notified-border: #a855f7;
  --queue-notified-text: #7e22ce;

  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
}

body {
  font-family: var(--font-sans);
